".{{= name }} {
    width: 100%;
}
.bj-hand-label {
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 1px;
    opacity: 0.6;
    margin-bottom: 8px;
}
.bj-hand-cards {
