".{{= name }} {
    width: 58px;
    height: 84px;
    background: white;
    border-radius: 7px;
    color: #111;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    box-shadow: 1px 2px 5px rgba(0,0,0,0.4);
    flex-shrink: 0;
    user-select: none;
    -webkit-user-select: none;
}
.{{= name }}.red {
    color: #cc0000;
}
.{{= name }}.face-down {
    background: #1a3a6b;
    background-image:
        repeating-linear-gradient(
            45deg,
            rgba(255,255,255,0.07) 0px, rgba(255,255,255,0.07) 2px,
            transparent 2px, transparent 10px
        );
}
.{{= name }}.face-down .card-rank,
.{{= name }}.face-down .card-suit { display: none; }
.card-rank { font-size: 20px; line-height: 1; }
.card-suit { font-size: 26px; line-height: 1; margin-top: 2px; }"

".{{= name }} {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.bj-btn {
    width: 100%;
    padding: 18px;
    font-size: 20px;
    font-weight: bold;
    border: none;
    border-radius: 10px;
    cursor: pointer;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    letter-spacing: 0.5px;
}
.bj-deal   { background: #f59e0b; color: #111; }
.bj-hit    { background: #16a34a; color: white; flex: 1; }
.bj-stand  { background: #dc2626; color: white; flex: 1; }
.bj-double { background: #7c3aed; color: white; flex: 1; }
.bj-action-row {
    display: flex;
    gap: 8px;
}
.bj-action-row .bj-btn { width: auto; }
.bj-bet-row {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    justify-content: center;
}
.bj-chip {
    padding: 12px 16px;
    font-size: 16px;
    font-weight: bold;
    border: 2px solid rgba(255,255,255,0.25);
    border-radius: 50px;
    background: rgba(255,255,255,0.1);
    color: white;
    cursor: pointer;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition: background 0.1s;
}
.bj-chip.active {
    background: #f59e0b;
    color: #111;
    border-color: #f59e0b;
}"

